INSERT INTO teacher_reference_questions (subject, question_type, content_json, source, enabled) VALUES ('英语[职高]', 'SINGLE_CHOICE', '{"questionText": "— You look great in that pink dress. — ______", "options": ["A. Where did you buy it?", "B. You''re welcome.", "C. Thank you.", "D. Enjoy yourself."], "correctAnswer": "C", "explanation": "考查情景交际。对方赞美时应当表示感谢。故选C。"}', 'REAL_EXAM', 1);
INSERT INTO teacher_reference_questions (subject, question_type, content_json, source, enabled) VALUES ('英语[职高]', 'SINGLE_CHOICE', '{"questionText": "I had ______ big lunch at my friend''s yesterday.", "options": ["A. a", "B. an", "C. /", "D. the"], "correctAnswer": "A", "explanation": "考查冠词辨析。have a big lunch 为固定搭配，''big''以辅音音素开头，用a。故选A。"}', 'REAL_EXAM', 1);
INSERT INTO teacher_reference_questions (subject, question_type, content_json, source, enabled) VALUES ('英语[职高]', 'SINGLE_CHOICE', '{"questionText": "Up to now, no one except Eric and Chris ______ the possible danger.", "options": ["A. have realized", "B. has realized", "C. is realizing", "D. are realizing"], "correctAnswer": "B", "explanation": "考查时态及主谓一致。''Up to now''与现在完成时连用；主语''no one''为单数，谓语用has。故选B。"}', 'REAL_EXAM', 1);
INSERT INTO teacher_reference_questions (subject, question_type, content_json, source, enabled) VALUES ('英语[职高]', 'SINGLE_CHOICE', '{"questionText": "John, you should learn to behave ______ at the dinner party.", "options": ["A. you", "B. yours", "C. yourself", "D. yourselves"], "correctAnswer": "C", "explanation": "考查反身代词。behave yourself 意为''守规矩''，主语you指John一人，用yourself。故选C。"}', 'REAL_EXAM', 1);
INSERT INTO teacher_reference_questions (subject, question_type, content_json, source, enabled) VALUES ('英语[职高]', 'SINGLE_CHOICE', '{"questionText": "Do you know that the concert is scheduled ______ the evening of August 5?", "options": ["A. on", "B. in", "C. at", "D. of"], "correctAnswer": "A", "explanation": "考查介词辨析。具体某一天的下午或晚上用介词on。故选A。"}', 'REAL_EXAM', 1);
INSERT INTO teacher_reference_questions (subject, question_type, content_json, source, enabled) VALUES ('英语[职高]', 'SINGLE_CHOICE', '{"questionText": "I''m truly ______ for what you''ve done for me.", "options": ["A. welcome", "B. grateful", "C. pleasant", "D. willing"], "correctAnswer": "B", "explanation": "考查形容词辨析。be grateful for 意为''对……感激''。故选B。"}', 'REAL_EXAM', 1);
